/* Consistent dismiss controls and compact collaborator selectors for every dialog. */
(()=>{'use strict';
function fold(dialog){dialog.querySelectorAll('fieldset').forEach(field=>{if(field.dataset.collapsedCollaborators||!field.querySelector('input[name="collaborators"]'))return;field.dataset.collapsedCollaborators='true';const legend=field.querySelector('legend'),details=document.createElement('details'),summary=document.createElement('summary'),content=document.createElement('div');details.className='dialog-collaborators';summary.textContent=legend?.textContent||'همکاران (اختیاری)';details.append(summary,content);[...field.childNodes].forEach(n=>{if(n!==legend)content.append(n)});field.replaceChildren(details);if(legend)legend.remove()})}
function position(dialog){const button=dialog.querySelector(':scope > .dialog-outside-close');if(!button||!dialog.open)return;const r=dialog.getBoundingClientRect(),scale=r.width/(dialog.offsetWidth||r.width)||1;button.style.left=Math.max(8,Math.min(innerWidth-44,r.right-34))/scale+'px';button.style.top=Math.max(6,r.top-43)/scale+'px'}
function enhance(dialog){if(!dialog.open)return;fold(dialog);let button=dialog.querySelector(':scope > .dialog-outside-close');if(!button){button=document.createElement('button');button.type='button';button.className='dialog-outside-close';button.textContent='×';button.setAttribute('aria-label','بستن پنجره');button.onclick=()=>dialog.close();dialog.append(button)}position(dialog)}
function bind(dialog){if(dialog.dataset.dismissReady)return;dialog.dataset.dismissReady='true';let outside=false;const isOutside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom};dialog.addEventListener('pointerdown',e=>{outside=e.target===dialog&&isOutside(e)});dialog.addEventListener('click',e=>{if(outside&&e.target===dialog&&isOutside(e))dialog.close();outside=false});dialog.addEventListener('close',()=>{outside=false;dialog.querySelector(':scope > .dialog-outside-close')?.remove()});new MutationObserver(()=>enhance(dialog)).observe(dialog,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});enhance(dialog)}
document.querySelectorAll('dialog').forEach(bind);new MutationObserver(()=>document.querySelectorAll('dialog').forEach(bind)).observe(document.body,{childList:true,subtree:true});window.addEventListener('resize',()=>document.querySelectorAll('dialog[open]').forEach(position));
})();
